"""Connected native Windows image-stage fixtures. Tiny generated bytes, no network/GPU/sensor."""
import argparse
import copy
import ctypes
import gzip
import hashlib
import http.client
import io
import json
import os
from pathlib import Path
import subprocess
import sys
import time
import uuid
from unittest.mock import patch

import image_admission as admission
import image_stage as stage

ROOT = admission.HERE.parents[1] / '.runtime/guarded-image-rehearsals'
CASES = ('success', 'cpu-hot', 'stale-feed', 'lost-feed', 'cancel', 'blocked-read',
         'blocked-expand', 'monitor-stall', 'partial-result', 'bad-hash', 'reader-stop-fail',
         'controller-lease', 'no-cool-baseline', 'chunked-auth', 'bad-chunked-auth',
         'blocked-chunked-auth', 'owner-death')


def checked(directory):
    directory = Path(directory).absolute()
    stage.download.tools.plain(directory)
    if (directory.parents[1] != ROOT or directory.name not in CASES or
            not stage.build.guard.re.fullmatch('[0-9a-f]{32}', directory.parent.name)):
        raise ValueError('Fixed guarded-image fixture namespace required')
    return directory


def fixture():
    data = b'generated harmless image-stage fixture\n' * 4
    packed = gzip.compress(data, mtime=0)
    configuration = b'{}'
    thermal = copy.deepcopy(stage.policy.load_effective_controls())
    thermal['temperature'].update(coolBaselineSeconds=.2, maxSampleAgeSeconds=.4)
    thermal['resources']['deadlineSeconds'] = 6
    packet = {'scope': 'synthetic-guarded-image-only', 'synthetic': True,
        'image': {'configDigest': 'sha256:' + hashlib.sha256(configuration).hexdigest(), 'configBytes': len(configuration),
                  'layers': [{'digest': 'sha256:' + hashlib.sha256(packed).hexdigest(), 'bytes': len(packed),
                              'expandedSha256': hashlib.sha256(data).hexdigest()}]},
        'thermalPolicy': thermal, 'readerSamples': 100, 'baselineWaitSeconds': 3, 'outerSeconds': 9,
        'workSeconds': 6, 'blobSeconds': 4, 'workerLeaseSeconds': 1.5,
        'controllerLeaseSeconds': .7, 'stopSeconds': 1,
        'budget': {'payloadBytes': 65536, 'namespaceBytes': 2 * 1024**2, 'supervisorReserveBytes': 1024**2,
                   'freeReserveBytes': 0, 'expandedLayerBytes': 65536, 'expandedTotalBytes': 65536}}
    return packet, configuration, packed


class Feed:
    synthetic = True
    def __init__(self, directory, cancelled=lambda: False):
        self.directory, self.sequence, self.last = directory, 0, 0
        self.closed, self.stalled = False, False
        self.cancelled = cancelled
    def start_reader(self, *, samples):
        self.samples = samples  # No process or real sensor is started.
    def poll(self):
        scenario = self.directory.name
        if self.cancelled():
            (self.directory / 'cancel.request').touch(exist_ok=True)
        blocked = (self.directory / 'blocked').exists()
        if scenario == 'monitor-stall' and blocked and not self.stalled:
            self.stalled = True
            time.sleep(1.2)  # Real independent liveness thread must stop blocked child.
        now = time.monotonic()
        if now - self.last < .1 or (scenario == 'lost-feed' and blocked):
            return None
        self.last, self.sequence = now, self.sequence + 1
        if scenario == 'cancel' and blocked:
            (self.directory / 'cancel.request').touch(exist_ok=True)
        return {'version': 1, 'sequence': self.sequence, 'synthetic': True,
            'source': 'ASUS DSTS 0x00120094', 'error': None, 'validatedCpuSensor': True,
            'cpuTemperatureC': 95 if scenario == 'no-cool-baseline' else 97 if scenario == 'cpu-hot' and blocked else 65,
            'recordedAtUnix': time.time() - (10 if scenario == 'stale-feed' and blocked else 0),
            'querySeconds': .01, 'cpuThermalThrottling': None, 'readerRemainingSeconds': 90}
    def close(self):
        self.closed = True
        if self.directory.name == 'reader-stop-fail':
            raise OSError('Synthetic reader close failure')


def child(directory):
    directory = checked(directory)
    packet, configuration, packed = fixture()
    # Native evidence of the effective worker mask; no busy loop/stress test.
    kernel = stage.windows_job.api()
    allowed, system = ctypes.c_size_t(), ctypes.c_size_t()
    stage.windows_job.checked(kernel.GetProcessAffinityMask(kernel.GetCurrentProcess(), ctypes.byref(allowed), ctypes.byref(system)))
    if allowed.value.bit_count() != 1:
        raise AssertionError('Worker affinity is not one logical processor')
    stage.download.tools.base.atomic(directory / 'affinity.json', {'logicalProcessors': allowed.value.bit_count()})
    payloads = {packet['image']['configDigest']: configuration, packet['image']['layers'][0]['digest']: packed}
    scenario = directory.name
    class Body(io.BytesIO):
        status = 200
        def __init__(self, payload):
            super().__init__(payload)
            self.size = len(payload)
        def getheaders(self):
            return [('Content-Length', str(self.size))]
        def read1(self, count):
            if scenario in ('cpu-hot', 'stale-feed', 'lost-feed', 'cancel', 'blocked-read', 'monitor-stall', 'owner-death'):
                (directory / 'blocked').touch(exist_ok=True)
                time.sleep(30)
            if scenario == 'controller-lease':
                time.sleep(.3)
                count = min(count, 1)
            return super().read(count)
    class Source:
        def __init__(self, blobs):
            if {b.digest for b in blobs} != set(payloads):
                raise AssertionError('Fixture descriptors changed')
        def open(self, blob, context):
            payload = payloads[blob.digest]
            return Body(payload[:-1] + bytes([payload[-1] ^ 1]) if scenario == 'bad-hash' else payload)
    def source_factory(blobs):
        if scenario not in ('chunked-auth', 'bad-chunked-auth', 'blocked-chunked-auth'):
            return Source(blobs)
        ordinal = 0
        token = b'{"token":"synthetic.token"}'
        class Stream(io.BytesIO):
            def read1(self, count):
                if scenario == 'blocked-chunked-auth':
                    (directory / 'blocked').touch(exist_ok=True)
                    time.sleep(30)
                return super().read1(count)
        class Socket:
            def makefile(self, mode):
                ending = b'' if scenario == 'bad-chunked-auth' else b'0\r\n\r\n'
                return Stream(b'HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n' +
                              f'{len(token):x}\r\n'.encode() + token + b'\r\n' + ending)
        class Opener:
            def open(self, request, *, timeout):
                if request.full_url == 'https://auth.docker.io/token?service=registry.docker.io&scope=repository:nvidia/cuda:pull':
                    response = http.client.HTTPResponse(Socket())
                    response.begin()
                    return response
                expected = 'https://registry-1.docker.io/v2/nvidia/cuda/blobs/'
                if request.full_url.startswith(expected) and request.full_url[len(expected):] in payloads:
                    return Body(payloads[request.full_url[len(expected):]])
                raise AssertionError('Unexpected fixture request; no network opener exists')
        def observation(record):
            nonlocal ordinal
            ordinal += 1
            stage.download.tools.base.atomic(directory / ('auth-response-' + str(ordinal) + '.json'), record)
        return stage.download.RegistrySource(blobs, opener=Opener(), on_auth_headers=observation)
    original_layer = stage.expand._layer
    def layer(*args, **kwargs):
        if scenario == 'blocked-expand':
            (directory / 'blocked').touch(exist_ok=True)
            time.sleep(30)
        return original_layer(*args, **kwargs)
    with patch.object(stage.expand, '_layer', side_effect=layer):
        stage.pipeline(directory, packet, source_factory, synthetic=True)
    if scenario == 'partial-result':
        stage.download.tools.base.atomic(directory / 'worker-result.json', {'synthetic': True, 'streams': {}})


def supervise(directory, *, witness=False, cancelled=lambda: False):
    directory = checked(directory)
    directory.mkdir(exist_ok=True)
    packet, _, _ = fixture()
    with stage.download.tools.base.lock(directory / 'control'):
        def launch():
            environment = {k: os.environ[k] for k in ('SystemRoot', 'TEMP', 'TMP') if k in os.environ}
            process = stage.windows_job.Process([sys.executable, '-B', '-E', '-s', str(Path(__file__).resolve()),
                    '--synthetic-child', str(directory)], cwd=directory, env=environment, single_cpu=True)
            if witness:
                stage.download.tools.base.atomic(directory / 'owner.ready.json', {'witness': process.witness_for_parent()})
            return process
        original_pulse = stage.controller.pulse
        def pulse(path, **kwargs):
            if directory.name == 'controller-lease' and path.name == 'controller.pulse' and path.exists():
                return  # Fixed synthetic loss only; never used by the live runner.
            return original_pulse(path, **kwargs)
        with patch.object(stage.controller, 'pulse', side_effect=pulse):
            return stage._execute(directory, packet, Feed(directory, cancelled), launch, synthetic=True)


def owner_death(directory):
    directory = checked(directory)
    directory.mkdir()
    owner = witness = None
    try:
        owner = subprocess.Popen([sys.executable, '-B', '-E', '-s', str(Path(__file__).resolve()),
            '--orphan-owner', str(directory)], stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL, creationflags=subprocess.CREATE_NO_WINDOW)
        end = time.monotonic() + 8
        while not ((directory / 'owner.ready.json').exists() and (directory / 'blocked').exists()):
            if time.monotonic() > end or owner.poll() is not None:
                raise AssertionError('Owner fixture setup failed')
            time.sleep(.025)
        record = json.loads(admission.cpu.bounded(directory / 'owner.ready.json', 4096))
        witness = stage.windows_job.Witness(record['witness'])
        if witness.poll() is not None:
            raise AssertionError('Worker was not alive before owner death')
        started = time.monotonic()
        owner.kill()
        owner.wait(timeout=2)
        witness.wait(timeout=2)
        elapsed = time.monotonic() - started
        try:
            supervise(directory)
        except stage.download.StageError as error:
            if error.code != 'IMAGE_STAGE_RESTART_REJECTED':
                raise
        else:
            raise AssertionError('Unfinished session restarted')
        return {'phase': 'FAULT', 'fault': 'SUPERVISOR_EXIT', 'stopConfirmed': True, 'readerStopped': True,
                'workerStopElapsedSeconds': elapsed, 'restartRejected': True,
                'note': 'No real reader existed; unfinished state denies retry after abrupt owner death.'}
    finally:
        if owner is not None and owner.poll() is None:
            owner.kill()
            owner.wait(timeout=2)
        if witness is not None:
            witness.close()


def verify(*, cancelled=lambda: False):
    stage.download.tools.plain(ROOT)
    with stage.download.tools.base.lock(ROOT / 'control'):
        entries, used = stage.download.plain_usage(ROOT)
        if entries + 500 > stage.download.ENTRY_LIMIT or used + 8 * 1024**2 > 32 * 1024**2:
            raise ValueError('Guarded fixture evidence namespace full')
        directory = ROOT / uuid.uuid4().hex
        directory.mkdir()
        result = {'directory': str(directory), 'passed': False, 'synthetic': True, 'networkUsed': False,
                  'realSensorRead': False, 'realImageBytesUsed': False, 'dockerUsed': False, 'cases': []}
        expected = {'cpu-hot': 'CPU_HOT', 'stale-feed': 'SENSOR_STALE', 'lost-feed': 'SENSOR_STALE',
            'cancel': 'CANCELLED', 'blocked-read': 'WORKER_PROGRESS_LOST', 'blocked-expand': 'WORKER_PROGRESS_LOST',
            'monitor-stall': 'MONITOR_LOOP_LOST', 'partial-result': 'WORKER_RESULT_INVALID',
            'bad-hash': 'IMAGE_WORKER_FAILED', 'reader-stop-fail': 'READER_STOP_UNCONFIRMED',
            'controller-lease': 'IMAGE_WORKER_FAILED', 'no-cool-baseline': 'BASELINE_WAIT_DEADLINE',
            'bad-chunked-auth': 'IMAGE_WORKER_FAILED', 'blocked-chunked-auth': 'WORKER_PROGRESS_LOST',
            'owner-death': 'SUPERVISOR_EXIT'}
        try:
            for name in CASES:
                if cancelled():
                    raise stage.download.StageError('CANCELLED')
                state = owner_death(directory / name) if name == 'owner-death' else supervise(directory / name, cancelled=cancelled)
                result['cases'].append({'scenario': name, **state})
                if cancelled():
                    raise stage.download.StageError('CANCELLED')
                if (state['fault'] != expected.get(name) or state['stopConfirmed'] is not True or
                        (name != 'reader-stop-fail' and state['readerStopped'] is not True)):
                    raise AssertionError('Unexpected connected fixture result: ' + name)
                if name != 'owner-death':
                    if state['workerStarted']:
                        proof = json.loads(admission.cpu.bounded(directory / name / 'affinity.json', 4096))
                        if proof != {'logicalProcessors': 1}:
                            raise AssertionError('Native worker affinity mismatch')
                    elif name != 'no-cool-baseline' or (directory / name / 'affinity.json').exists():
                        raise AssertionError('Unexpected missing worker or work before baseline')
                    try:
                        supervise(directory / name)
                    except stage.download.StageError as error:
                        if error.code != 'IMAGE_STAGE_RESTART_REJECTED':
                            raise
                    else:
                        raise AssertionError('Connected fixture restarted')
                if name == 'chunked-auth':
                    if state['result']['staged']['authPayloadBytes'] <= 0:
                        raise AssertionError('Actual auth decoder was not exercised')
                    observed = json.loads(admission.cpu.bounded(directory / name / 'auth-response-1.json', 4096))
                    if observed['transferEncoding'] != 'chunked' or observed['declaredBytes'] is not None:
                        raise AssertionError('Observed framing was not reproduced')
                elif name in ('bad-chunked-auth', 'blocked-chunked-auth'):
                    child_state = json.loads(admission.cpu.bounded(directory / name / 'data/state.json', 131072))
                    if child_state['blobs'] or list((directory / name / 'data/cache').iterdir()):
                        raise AssertionError('Failed auth promoted blob bytes')
                result['cases'][-1]['restartRejected'] = True
                if state.get('workerStopElapsedSeconds', 0) > 2:
                    raise AssertionError('Fixture stop exceeded bounded budget')
            result['passed'] = True
        finally:
            stage.download.tools.base.atomic(directory / 'result.json', result)
        print(json.dumps({'directory': str(directory), **result}, indent=2))
        return result


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument('--execute-synthetic-only', action='store_true')
    mode.add_argument('--synthetic-child')
    mode.add_argument('--orphan-owner')
    options = parser.parse_args()
    if options.synthetic_child:
        try:
            child(options.synthetic_child)
        except BaseException:
            raise SystemExit(3)
    elif options.orphan_owner:
        supervise(options.orphan_owner, witness=True)
    else:
        verify()
